import anthropic
import json
import re


def post(acct: str, cents: int, reason: str) -> str:
    """Post a transaction to the ledger using Claude."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post_transaction",
            "description": "Post a transaction to the ledger with an account, amount in cents, and reason",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "reason": {
                        "type": "string",
                        "description": "The reason/memo for the transaction"
                    }
                },
                "required": ["account", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for content_block in response.content:
            if content_block.type == "tool_use":
                tool_input = content_block.input
                entry_id = _simulate_ledger_post(
                    tool_input["account"],
                    tool_input["cents"],
                    tool_input["reason"]
                )
                return entry_id

    return None


def _simulate_ledger_post(acct: str, cents: int, reason: str) -> str:
    """Simulate posting to a ledger and return an entry ID."""
    import hashlib

    entry_data = f"{acct}:{cents}:{reason}"
    entry_id = hashlib.md5(entry_data.encode()).hexdigest()[:8]

    return entry_id


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer `cents` to account `acct` using `reason` as the memo.
    Returns the entry id.
    """
    return post(acct, cents, reason)


if __name__ == "__main__":
    result = transfer("checking", 10000, "Monthly salary")
    print(f"Entry ID: {result}")
