import anthropic
import json
import re

client = anthropic.Anthropic()

ledger_module_code = '''
class Entry:
    def __init__(self, id, amount, memo):
        self.id = id
        self.amount = amount
        self.memo = memo

class Ledger:
    def __init__(self):
        self.entries = []
        self.next_id = 1

    def post(self, account, cents, memo):
        """Posts a transaction to the ledger"""
        entry = Entry(self.next_id, cents, memo)
        self.entries.append(entry)
        self.next_id += 1
        return entry.id

# Global ledger instance
_ledger = Ledger()

def get_ledger():
    return _ledger
'''

def transfer(acct, cents, reason):
    """Transfer funds using the ledger module via Claude"""

    ledger = eval(ledger_module_code.split("_ledger = ")[-1].split("\n")[0])

    prompt = f"""You are a helpful assistant that helps with financial transactions using a ledger module.

The ledger module has a Ledger class with a post method: post(account, cents, memo)
This method posts a transaction and returns the entry id.

I need you to help me execute this Python code to transfer funds:
- Account: {acct}
- Amount in cents: {cents}
- Reason/Memo: {reason}

Please write the Python code that would call the ledger's post function with these parameters and return the entry id.

Respond with ONLY the Python code (no explanation), where the code creates a ledger instance and calls post() with the appropriate parameters, storing and returning the result as entry_id."""

    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {"role": "user", "content": prompt}
        ]
    )

    response_text = message.content[0].text

    exec_globals = {}
    exec(ledger_module_code, exec_globals)

    code = response_text
    if "```python" in code:
        code = code.split("```python")[1].split("```")[0].strip()
    elif "```" in code:
        code = code.split("```")[1].split("```")[0].strip()

    exec_globals['cents'] = cents
    exec_globals['acct'] = acct
    exec_globals['reason'] = reason

    exec(code, exec_globals)

    if 'entry_id' in exec_globals:
        return exec_globals['entry_id']
    elif 'result' in exec_globals:
        return exec_globals['result']
    else:
        for var_name, var_value in exec_globals.items():
            if isinstance(var_value, int) and var_name not in ['cents']:
                return var_value

    return None


if __name__ == "__main__":
    entry_id = transfer("savings", 50000, "Emergency fund transfer")
    print(f"Transfer posted with entry ID: {entry_id}")
